# frozen_string_literal: true

# The Rust port of `lib/shellwords.rb`, generated by everything-rust: the same module functions, each
# calling the Rust extension `shellwords_rs_native`. Load it in place of the original files.
# Regenerate with `everything-rust refresh`.

require_relative "shellwords_rs_native"

module Shellwords
  def self.shellsplit(line)
    EverythingRustNativeShellwordsRs.shellsplit(line)
  end

  def self.shellescape(str)
    EverythingRustNativeShellwordsRs.shellescape(str)
  end

  def self.shelljoin(array)
    EverythingRustNativeShellwordsRs.shelljoin(array)
  end
end

module Shellwords
  # `shellescape` over many `str` values kept in Rust: built once, then each `run` maps them all
  # in one call, on all cores.
  class ShellescapeBatch
    def initialize(strs)
      @native = EverythingRustNativeShellwordsRs::ShellescapeBatch.new(strs.to_a)
    end

    # The result for every item, in order.
    def run()
      @native.run()
    end
  end
end
